const j = $input.first().json;
const route = j.mode ? String(j.mode) : ((j.submittedAt || j.formMode) ? 'form' : 'monitor');
const key = p => { p = String(p).toLowerCase(); return p.includes('meta') || p.includes('facebook') ? 'meta' : p.includes('tiktok') ? 'tiktok' : p.includes('snap') ? 'snapchat' : p.includes('google') ? 'google' : ''; };
const platforms = [...new Set([].concat(j.platforms || []).map(key).filter(Boolean))];
const split = s => [].concat(s || []).join(',').split(/[\n,]+/).map(x => x.trim()).filter(Boolean);
const cid = s => String(s || '').replace(/[^0-9]/g, '');
return [{ json: {
  route,
  brand: String(j.brand || '').trim(),
  product: String(j.product || '').trim(),
  objective: ['Awareness', 'Traffic', 'Engagement', 'Leads', 'Sales'].includes(j.objective) ? j.objective : 'Traffic',
  daily_budget: Number(j.daily_budget) || 0,
  start_date: j.start_date || $today.plus({ days: 1 }).toISODate(),
  countries: split(j.countries || 'EG').map(c => c.toUpperCase()).slice(0, 10),
  audience: String(j.audience || '').trim(),
  landing_url: String(j.landing_url || j.website || '').trim(),
  platforms,
  keywords: split(j.keywords).slice(0, 30),
  language: j.language === 'English' ? 'English' : 'Arabic',
  notes: String(j.notes || j.campaign_context || '').trim(),
  plan: j.plan || null,
  approved_platforms: j.approved_platforms ? [].concat(j.approved_platforms).map(key).filter(Boolean) : null,
  meta_ad_account_id: String(j.meta_ad_account_id || '').replace(/^act_/, '').trim(),
  tiktok_advertiser_id: String(j.tiktok_advertiser_id || '').trim(),
  snap_ad_account_id: String(j.snap_ad_account_id || '').trim(),
  google_ads_customer_id: cid(j.google_ads_customer_id),
  google_ads_login_customer_id: cid(j.google_ads_login_customer_id || j.google_ads_customer_id)
} }];

const s = $('Ads Settings').first().json;
const n = $('Normalize Ads Request').first().json;
const key = p => { p = String(p).toLowerCase(); return p.includes('meta') || p.includes('facebook') ? 'meta' : p.includes('tiktok') ? 'tiktok' : p.includes('snap') ? 'snapchat' : p.includes('google') ? 'google' : ''; };
let plan = {}, selected = [], approved = true;
if (n.route === 'form') {
  plan = $('Build Plan Review').first().json.plan || {};
  const f = $('Approve Campaign Launch').first().json;
  approved = /create/i.test(String(f.decision || ''));
  selected = [].concat(f.launch_platforms || []).map(key);
} else {
  plan = n.plan || {};
  selected = n.approved_platforms || n.platforms;
}
const ok = { meta: !!n.meta_ad_account_id, tiktok: !!n.tiktok_advertiser_id, snapchat: !!n.snap_ad_account_id, google: !!n.google_ads_customer_id };
const goal = n.objective;
const sd = DateTime.fromISO(String(n.start_date));
const startIso = sd.isValid && sd > $now ? sd.toISO() : $now.plus({ hours: 1 }).toISO();
const notes = [];
const out = { meta_items: [], tiktok_items: [], snap_items: [], google_items: [] };
const geo = { EG: 2818, SA: 2682, AE: 2784, KW: 2414, QA: 2634, JO: 2400, BH: 2048, OM: 2512, GB: 2826, US: 2840, MA: 2504, LB: 2422, IQ: 2368 };
const cut = (t, m) => String(t || '').trim().slice(0, m);
(plan.campaigns || []).forEach(c => {
  const p = key(c.platform);
  const budget = Number(c.daily_budget) || 0;
  if (!selected.includes(p) || budget <= 0) return;
  if (!ok[p]) { notes.push(p + ': account ID missing in Ads Settings - skipped'); return; }
  const t = c.targeting || {};
  const countries = [].concat(t.countries || n.countries).map(x => String(x).toUpperCase()).filter(x => /^[A-Z]{2}$/.test(x));
  const ageMin = Math.max(13, Number(t.age_min) || 18), ageMax = Math.min(65, Number(t.age_max) || 65);
  const name = cut(c.name || (n.brand + ' ' + goal + ' ' + p), 200) + ' [AI]';
  if (p === 'meta') {
    let objective = { Awareness: 'OUTCOME_AWARENESS', Traffic: 'OUTCOME_TRAFFIC', Engagement: 'OUTCOME_ENGAGEMENT', Leads: 'OUTCOME_LEADS', Sales: 'OUTCOME_SALES' }[goal];
    let opt = { Awareness: 'REACH', Traffic: 'LINK_CLICKS', Engagement: 'POST_ENGAGEMENT', Leads: 'OFFSITE_CONVERSIONS', Sales: 'OFFSITE_CONVERSIONS' }[goal];
    let promoted = null, destination = null;
    if ((goal === 'Leads' || goal === 'Sales') && s.meta_pixel_id) promoted = { pixel_id: s.meta_pixel_id, custom_event_type: goal === 'Sales' ? 'PURCHASE' : 'LEAD' };
    else if (goal === 'Leads' || goal === 'Sales') { objective = 'OUTCOME_TRAFFIC'; opt = 'LINK_CLICKS'; notes.push('meta: no meta_pixel_id in Ads Settings, so the campaign was created as Traffic instead of ' + goal); }
    if (goal === 'Engagement') destination = 'ON_POST';
    const targeting = { geo_locations: { countries }, age_min: ageMin, age_max: ageMax, targeting_automation: { advantage_audience: 0 } };
    if (t.gender === 'male') targeting.genders = [1];
    if (t.gender === 'female') targeting.genders = [2];
    const adset = { name: name + ' - Ad set', billing_event: 'IMPRESSIONS', optimization_goal: opt, status: 'PAUSED', start_time: startIso, targeting: JSON.stringify(targeting) };
    if (promoted) adset.promoted_object = JSON.stringify(promoted);
    if (destination) adset.destination_type = destination;
    out.meta_items.push({ name, budget, campaign: { name, objective, status: 'PAUSED', special_ad_categories: '[]', daily_budget: String(Math.round(budget * 100)), bid_strategy: 'LOWEST_COST_WITHOUT_CAP' }, adset });
  }
  if (p === 'tiktok') {
    out.tiktok_items.push({ name, budget, body: { advertiser_id: n.tiktok_advertiser_id, campaign_name: name.slice(0, 512), objective_type: { Awareness: 'REACH', Traffic: 'TRAFFIC', Engagement: 'ENGAGEMENT', Leads: 'LEAD_GENERATION', Sales: 'WEB_CONVERSIONS' }[goal], budget_mode: 'BUDGET_MODE_DAY', budget: Math.round(budget * 100) / 100, operation_status: 'DISABLE' } });
  }
  if (p === 'snapchat') {
    const micro = Math.round(budget * 1e6);
    out.snap_items.push({ name, budget,
      campaign_body: { campaigns: [{ name, ad_account_id: n.snap_ad_account_id, status: 'PAUSED', start_time: startIso, daily_budget_micro: micro, objective_v2_properties: { objective_v2_type: { Awareness: 'AWARENESS_AND_ENGAGEMENT', Engagement: 'AWARENESS_AND_ENGAGEMENT', Traffic: 'TRAFFIC', Leads: 'LEADS', Sales: 'SALES' }[goal] } }] },
      adsquad: { name: name + ' - Ad squad', type: 'SNAP_ADS', placement_v2: { config: 'AUTOMATIC' }, bid_strategy: 'AUTO_BID', optimization_goal: goal === 'Awareness' ? 'IMPRESSIONS' : 'SWIPES', billing_event: 'IMPRESSION', status: 'PAUSED', start_time: startIso, daily_budget_micro: micro, targeting: { regulated_content: false, geos: countries.map(cc => ({ country_code: cc.toLowerCase() })), demographics: [{ min_age: String(ageMin), max_age: String(ageMax) }] } } });
  }
  if (p === 'google') {
    const cid = n.google_ads_customer_id;
    const R = (type, id) => 'customers/' + cid + '/' + type + '/' + id;
    const ops = [];
    ops.push({ campaignBudgetOperation: { create: { resourceName: R('campaignBudgets', -1), name: name + ' budget ' + $now.toFormat('yyyyMMddHHmm'), amountMicros: String(Math.max(10000, Math.round(budget * 100) * 10000)), deliveryMethod: 'STANDARD', explicitlyShared: false } } });
    ops.push({ campaignOperation: { create: { resourceName: R('campaigns', -2), name, status: 'PAUSED', advertisingChannelType: 'SEARCH', campaignBudget: R('campaignBudgets', -1), targetSpend: {}, networkSettings: { targetGoogleSearch: true, targetSearchNetwork: true, targetContentNetwork: false, targetPartnerSearchNetwork: false }, containsEuPoliticalAdvertising: 'DOES_NOT_CONTAIN_EU_POLITICAL_ADVERTISING' } } });
    countries.forEach(cc => { if (geo[cc]) ops.push({ campaignCriterionOperation: { create: { campaign: R('campaigns', -2), location: { geoTargetConstant: 'geoTargetConstants/' + geo[cc] } } } }); });
    ops.push({ campaignCriterionOperation: { create: { campaign: R('campaigns', -2), language: { languageConstant: 'languageConstants/' + (n.language === 'English' ? 1000 : 1019) } } } });
    [].concat(c.negative_keywords || []).slice(0, 30).forEach(k => { if (cut(k, 80)) ops.push({ campaignCriterionOperation: { create: { campaign: R('campaigns', -2), negative: true, keyword: { text: cut(k, 80), matchType: 'PHRASE' } } } }); });
    ops.push({ adGroupOperation: { create: { resourceName: R('adGroups', -3), campaign: R('campaigns', -2), name: name + ' - Ad group', status: 'ENABLED', type: 'SEARCH_STANDARD' } } });
    [...new Set([].concat(c.google_keywords || [], n.keywords || []).map(k => cut(k, 80)).filter(Boolean))].slice(0, 25).forEach(k => ops.push({ adGroupCriterionOperation: { create: { adGroup: R('adGroups', -3), status: 'ENABLED', keyword: { text: k, matchType: 'PHRASE' } } } }));
    const cr = c.creative || {};
    const heads = [...new Set([].concat(cr.headlines || []).map(x => cut(x, 30)).filter(Boolean))].slice(0, 15);
    const descs = [...new Set([].concat(cr.descriptions || [], cr.primary_text ? [cr.primary_text] : []).map(x => cut(x, 90)).filter(Boolean))].slice(0, 4);
    if (heads.length >= 3 && descs.length >= 2 && /^https?:/i.test(n.landing_url)) ops.push({ adGroupAdOperation: { create: { adGroup: R('adGroups', -3), status: 'PAUSED', ad: { finalUrls: [n.landing_url], responsiveSearchAd: { headlines: heads.map(text => ({ text })), descriptions: descs.map(text => ({ text })) } } } } });
    else notes.push('google: responsive search ad skipped (needs 3+ headlines, 2+ descriptions and a landing URL)');
    out.google_items.push({ name, budget, body: { mutateOperations: ops } });
  }
});
return [{ json: Object.assign({ approved, route: n.route, notes, start: startIso }, out) }];

const n = $('Normalize Ads Request').first().json;
const s = $('Ads Settings').first().json;
function first(name) { try { return $(name).first().json || {}; } catch (e) { return {}; } }
const num = v => Number(v) || 0;
const rows = [], errors = {};
function err(p, r) { const e = r && (r.error || (r.code && r.code !== 0 ? r.message : null) || (r.request_status && r.request_status !== 'SUCCESS' ? (r.debug_message || r.request_status) : null)); if (e) errors[p] = (typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 300); }
const connected = { meta: !!n.meta_ad_account_id, tiktok: !!n.tiktok_advertiser_id, snapchat: !!n.snap_ad_account_id, google: !!n.google_ads_customer_id };
const convOf = acts => { const pick = ['purchase', 'offsite_conversion.fb_pixel_purchase', 'lead', 'onsite_conversion.lead_grouped', 'offsite_conversion.fb_pixel_lead', 'complete_registration']; for (const t of pick) { const a = (acts || []).find(x => x.action_type === t); if (a) return num(a.value); } return 0; };
if (connected.meta) {
  const ins = first('Meta Insights'); const camps = first('Meta Campaigns'); err('meta', ins); err('meta', camps);
  const byId = {}; (ins.data || []).forEach(r => { byId[r.campaign_id] = r; });
  (camps.data || []).forEach(c => { const m = byId[c.id] || {}; rows.push({ platform: 'meta', campaign_id: c.id, name: c.name, status: c.effective_status || c.status, objective: c.objective, daily_budget: c.daily_budget ? num(c.daily_budget) / 100 : null, spend: num(m.spend), impressions: num(m.impressions), clicks: num(m.clicks), conversions: convOf(m.actions), roas: m.purchase_roas ? num(m.purchase_roas[0] && m.purchase_roas[0].value) : null }); });
}
if (connected.tiktok) {
  const rep = first('TikTok Report'); const camps = first('TikTok Campaigns'); err('tiktok', rep); err('tiktok', camps);
  const byId = {}; ((rep.data && rep.data.list) || []).forEach(r => { byId[(r.dimensions || {}).campaign_id] = r.metrics || {}; });
  ((camps.data && camps.data.list) || []).forEach(c => { const m = byId[c.campaign_id] || {}; rows.push({ platform: 'tiktok', campaign_id: String(c.campaign_id), name: c.campaign_name, status: c.operation_status, objective: c.objective_type, daily_budget: c.budget_mode === 'BUDGET_MODE_DAY' ? num(c.budget) : null, spend: num(m.spend), impressions: num(m.impressions), clicks: num(m.clicks), conversions: num(m.conversion), roas: null }); });
}
if (connected.snapchat) {
  const camps = first('Snapchat Campaigns'); const st = first('Snapchat Stats'); err('snapchat', camps); err('snapchat', st);
  const byId = {};
  const ts = ((st.total_stats || [])[0] || {}).total_stat || {};
  (((ts.breakdown_stats || {}).campaign) || []).forEach(b => { byId[b.id] = b.stats || {}; });
  (camps.campaigns || []).forEach(w => { const c = w.campaign || {}; const m = byId[c.id] || {}; rows.push({ platform: 'snapchat', campaign_id: c.id, name: c.name, status: c.status, objective: (c.objective_v2_properties || {}).objective_v2_type || c.objective || '', daily_budget: c.daily_budget_micro ? num(c.daily_budget_micro) / 1e6 : null, spend: num(m.spend) / 1e6, impressions: num(m.impressions), clicks: num(m.swipes), conversions: num(m.conversion_purchases) + num(m.conversion_sign_ups), roas: null, raw: c }); });
}
if (connected.google) {
  const g = first('Google Ads Report'); err('google', g);
  (g.results || []).forEach(r => { const c = r.campaign || {}, b = r.campaignBudget || {}, m = r.metrics || {}; rows.push({ platform: 'google', campaign_id: String(c.id), name: c.name, status: c.status, objective: c.advertisingChannelType, daily_budget: b.amountMicros ? num(b.amountMicros) / 1e6 : null, budget_ref: b.resourceName || '', spend: num(m.costMicros) / 1e6, impressions: num(m.impressions), clicks: num(m.clicks), conversions: num(m.conversions), roas: num(m.costMicros) ? num(m.conversionsValue) / (num(m.costMicros) / 1e6) : null }); });
}
rows.forEach(r => { r.ctr = r.impressions ? Math.round(r.clicks / r.impressions * 10000) / 100 : 0; r.cpc = r.clicks ? Math.round(r.spend / r.clicks * 100) / 100 : null; r.cpa = r.conversions ? Math.round(r.spend / r.conversions * 100) / 100 : null; r.spend = Math.round(r.spend * 100) / 100; });
const totals = {};
rows.forEach(r => { const t = totals[r.platform] = totals[r.platform] || { spend: 0, clicks: 0, impressions: 0, conversions: 0, campaigns: 0 }; t.spend += r.spend; t.clicks += r.clicks; t.impressions += r.impressions; t.conversions += r.conversions; t.campaigns++; });
Object.values(totals).forEach(t => { t.spend = Math.round(t.spend); t.cpa = t.conversions ? Math.round(t.spend / t.conversions) : null; t.ctr = t.impressions ? Math.round(t.clicks / t.impressions * 10000) / 100 : 0; });
const perf_for_ai = JSON.stringify({ period: n.route === 'monitor' ? 'last 7 days' : 'last 30 days', currency: s.currency, totals, campaigns: rows.map(r => { const o = Object.assign({}, r); delete o.raw; delete o.budget_ref; return o; }), errors }).slice(0, 40000);
return [{ json: { ...n, rows, totals, errors, connected, perf_for_ai } }];

