function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  return typeof j.text === 'string' ? j.text : JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return { parse_error: true, raw: String(t || '') };
}
const d = $('Unify Performance').first().json;
const cur = $('Ads Settings').first().json.currency;
const plan = parseJson(textOf($input.first().json));
const label = { meta: 'Meta', tiktok: 'TikTok', snapchat: 'Snapchat', google: 'Google Ads' };
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
const td = 'style="border-bottom:1px solid #e4e7ec;padding:6px;vertical-align:top;text-align:start"';
let h = '<p>' + esc(plan.summary) + '</p>' + (plan.parse_error ? '<pre>' + esc(plan.raw) + '</pre>' : '');
h += '<h3>Budget split (' + esc(cur) + '/day)</h3><table style="width:100%;border-collapse:collapse">' + arr(plan.budget_split).map(b => '<tr><td ' + td + '><b>' + esc(label[b.platform] || b.platform) + '</b></td><td ' + td + '>' + esc(b.daily_budget) + ' (' + esc(b.share_pct) + '%)</td><td ' + td + '>' + esc(b.rationale) + '</td></tr>').join('') + '</table>';
h += arr(plan.campaigns).map(c => { const t = c.targeting || {}; const cr = c.creative || {}; return '<h3>' + esc(label[c.platform] || c.platform) + ': ' + esc(c.name) + ' - ' + esc(c.daily_budget) + ' ' + esc(cur) + '/day</h3><p><b>Targeting:</b> ' + esc(arr(t.countries).join(', ')) + ' · ' + esc(t.age_min) + '-' + esc(t.age_max) + ' · ' + esc(t.gender) + '<br><b>Interests:</b> ' + esc(arr(t.interests).join(', ')) + (t.audience_notes ? '<br>' + esc(t.audience_notes) : '') + (arr(c.google_keywords).length ? '<br><b>Keywords:</b> ' + esc(c.google_keywords.join(', ')) + '<br><b>Negatives:</b> ' + esc(arr(c.negative_keywords).join(', ')) : '') + '<br><b>Bidding:</b> ' + esc(c.bidding) + '<br><b>Headlines:</b> ' + esc(arr(cr.headlines).join(' | ')) + '<br><b>Text:</b> ' + esc(cr.primary_text) + (arr(cr.descriptions).length ? '<br><b>Descriptions:</b> ' + esc(cr.descriptions.join(' | ')) : '') + '</p>'; }).join('');
h += '<h3>KPIs</h3><ul>' + arr(plan.kpis).map(k => '<li>' + esc(label[k.platform] || k.platform) + ' - ' + esc(k.metric) + ': <b>' + esc(k.target) + '</b></li>').join('') + '</ul>';
if (arr(plan.risks).length) h += '<h3>Risks</h3><ul>' + plan.risks.map(r => '<li>' + esc(r) + '</li>').join('') + '</ul>';
if (Object.keys(d.errors || {}).length) h += '<p style="color:#b54708"><b>Data warnings:</b> ' + esc(Object.entries(d.errors).map(e => e[0] + ': ' + e[1]).join(' | ')) + '</p>';
const notConnected = d.platforms.filter(p => !d.connected[p]);
if (notConnected.length) h += '<p style="color:#b54708"><b>Not connected (fill the IDs in Ads Settings):</b> ' + esc(notConnected.map(p => label[p]).join(', ')) + ' - these cannot be created.</p>';
const planned = [...new Set(arr(plan.campaigns).filter(c => Number(c.daily_budget) > 0).map(c => c.platform))].filter(p => d.connected[p]);
const full = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="font:15px/1.6 system-ui,Segoe UI,Tahoma,sans-serif;max-width:1000px;margin:24px auto;padding:0 16px"><h1>Media plan: ' + esc(d.brand) + '</h1>' + h + '</body></html>';
return [{ json: { route: d.route, plan, plan_html: h, html: full, launch_labels: planned.map(p => label[p]).join(',') } }];

